// Assistent fragen (ALLY 30, BA5, Stefan 20.10.2026): Frage an den Assistenten, die Antwort kommt in den Chat (Element). Daten wie ALLY 8 (arbeit_web_seite 'fragen').
// Aktion mit Namen und Feld von ALLY 8: fragen (text). Kein Knopf zum Öffnen des Chats. Liefert nur die Seitenbeschreibung (JSON).
// BA10 (Migration 69): Abschnitt „Deine Fragen“ (ally_assistent_ui, nur eigene, 30 Tage) mit der Antwort im Seitenfenster (fr=<id>); die Antwort merkt ALLY 1.
const E = $('Start').first().json;
const D = $input.first().json || {};
const F = E.funktion || {};
const titel = String(F.name || 'Fragen');
const kopf = { schluessel: 'fragen', art: 'funktion', titel, beschreibung: String(F.beschreibung || ''), krumen: [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: titel }] };
if (/^[a-z0-9-]{1,40}$/.test(String(F.einstellungen_ziel || ''))) kopf.zahnrad = { ziel: { seite: 'einstellungen', parameter: { bereich: String(F.einstellungen_ziel) } } };
if (D.ok !== true || !D.f) return [{ json: { inhalt: { seite: kopf, bloecke: [{ typ: 'hinweis', ton: 'warn', text: 'Die Seite konnte nicht geladen werden. Bitte neu laden.' }] } } }];
const pn = String(D.produkt || '').trim();
if (D.f.chat !== true) return [{ json: { inhalt: { seite: kopf, bloecke: [{ typ: 'hinweis', ton: 'warn', text: 'Für dich ist kein Chat eingerichtet. Die Antworten kommen in den Chat, ohne Chat ist diese Seite nicht nutzbar.' }] } } }];
const bloecke = [{ typ: 'formular', id: 'frage', aktion: 'fragen', titel: 'Frage stellen', frage: 'Frage senden? Die Antwort kommt in den Chat und steht danach hier unter „Deine Fragen“.',
  felder: [{ typ: 'textbereich', name: 'text', label: 'Deine Frage', pflicht: true, zeilen: 5, breite: 'voll', platzhalter: 'z. B. Welche Rechnungen sind seit mehr als 30 Tagen offen?' }],
  knoepfe: [{ text: 'Frage senden' }] }];
// BA10: Deine Fragen
const V = (Array.isArray(D.v) ? D.v : []).filter(x => x && /^[0-9]{1,12}$/.test(String(x.id)));
const frW = String(($('Parameter').first().json || {}).fr || '');
const hierF = extra => ({ seite: 'fragen', parameter: Object.assign({}, extra || {}), anker: 'a-verlauf' });
const kurz = t => { const x = String(t || '').replace(/\s+/g, ' ').trim(); return x.length > 140 ? x.slice(0, 139) + '…' : x; };
const status = x => x.antwort ? { text: 'beantwortet', ton: 'ok' } : x.wartet ? { text: 'wartet', ton: 'info' } : { text: 'ohne Antwort', ton: 'grau' };
const abschnitte = [{ id: 'verlauf', titel: 'Deine Fragen', zahl: Number(V.length).toLocaleString('de-DE'), offen_standard: V.length > 0,
  info: 'Deine Fragen der letzten 30 Tage mit der Antwort. Eine neue Antwort erscheint nach etwa einer Minute, dafür die Seite neu laden.',
  inhalt: [{ typ: 'liste', leer: 'Noch keine Fragen.', eintraege: V.map(x => ({ marke: status(x), text: kurz(x.frage), neben: String(x.zeit || ''), ziel: hierF({ fr: String(x.id) }), ziel_text: 'Ansehen' })) }] }];
const absaetze = t => { const L = String(t || '').split(/\n{2,}/).map(x => x.trim()).filter(Boolean); return L.length ? L.map(x => ({ typ: 'text', text: x })) : []; };
const sel = frW ? V.find(x => String(x.id) === frW) : null;
const fenster = sel ? [{ id: 'frage-verlauf', art: 'seitenfenster', offen: true, titel: 'Frage vom ' + String(sel.zeit || ''), untertitel: status(sel).text, schliessen_ziel: hierF({}),
  inhalt: [{ typ: 'unterueberschrift', text: 'Frage' }].concat(absaetze(sel.frage), [{ typ: 'unterueberschrift', text: 'Antwort' }],
    sel.antwort ? absaetze(sel.antwort) : [{ typ: 'text', ton: 'grau', text: sel.wartet ? 'Die Antwort ist noch unterwegs. Bitte die Seite gleich neu laden.' : 'Zu dieser Frage ist keine Antwort gespeichert. Sie steht im Chat.' }]) }] : [];
return [{ json: { inhalt: { seite: kopf, bloecke, abschnitte, fenster } } }];

// Parameter (ALLY 30, Assistent fragen): Sitzung für die Datenbank (nur 64 Hex-Zeichen, sonst leer = nicht angemeldet). BA10: gewählte Frage (fr, nur Ziffern).
const E = $input.first().json;
return [{ json: { werte: [/^[0-9a-f]{64}$/.test(String(E.sitzung || '')) ? String(E.sitzung) : ''], fr: /^[0-9]{1,12}$/.test(String((E.parameter || {}).fr || '')) ? String(E.parameter.fr) : '' } }];
